def esc(s): return html.escape(s,quote=True)
def svg(title,slug,i):
    # Local generated illustration; no external image dependencies.
    hue=(i*37+28)%360
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><defs><radialGradient id="bg"><stop stop-color="hsl({hue} 35% 42%)"/><stop offset="1" stop-color="hsl({hue} 38% 14%)"/></radialGradient><radialGradient id="s"><stop stop-color="#d9a548"/><stop offset="1" stop-color="#6e3518"/></radialGradient></defs><rect width="1200" height="800" fill="url(#bg)"/><ellipse cx="600" cy="420" rx="390" ry="235" fill="#e7ddd0"/><ellipse cx="600" cy="410" rx="330" ry="175" fill="url(#s)"/><g fill="#f2c66d" opacity=".7"><circle cx="470" cy="380" r="18"/><circle cx="710" cy="450" r="13"/><circle cx="630" cy="330" r="15"/></g><g fill="#5f9b54"><ellipse cx="530" cy="400" rx="18" ry="42" transform="rotate(45 530 400)"/><ellipse cx="690" cy="370" rx="15" ry="38" transform="rotate(-40 690 370)"/></g><path d="M500 210c-45-65 45-80 0-145M600 195c-45-65 45-80 0-145M700 210c-45-65 45-80 0-145" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="13" stroke-linecap="round"/><rect y="650" width="1200" height="150" fill="#12372c" fill-opacity=".96"/><text x="600" y="720" fill="white" font-family="Georgia,serif" font-size="50" text-anchor="middle">{esc(title)}</text><text x="600" y="765" fill="#dec99b" font-family="Arial,sans-serif" font-size="21" text-anchor="middle">THE KITCHEN TABLE · GENERATED LOCALLY</text></svg>'''

# Existing birria-consome is the canonical recipe. Do not create a duplicate page.
existing={"birria-consome"}
for i,(title,slug,region,desc,ings,steps,rels) in enumerate(items):
    (AS/f"{slug}.svg").write_text(svg(title,slug,i),encoding="utf-8")
    if slug in existing: continue
    related=" · ".join(f'<a class="text-link" href="{r}.html">{r.replace("-"," ").title()} →</a>' for r in rels)
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(desc)}"><title>{esc(title)} | The Kitchen Table</title><link rel="stylesheet" href="styles.css"></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html">The Kitchen Table</a><nav class="nav"><a href="index.html#recipes">Recipes</a><a href="plan-a-meal.html">Plan a Meal</a></nav></div></header><main class="section recipe-detail"><div class="container"><a class="text-link" href="index.html#recipes">← Back to all recipes</a><p class="eyebrow" style="margin-top:24px">BROTH &amp; STOCK · {esc(region.upper())}</p><h1>{esc(title)}</h1><p class="recipe-intro">{esc(desc)}</p><div class="stats"><span>Broth &amp; Stock</span><span>{esc(region)}</span></div><button class="button secondary print-button" onclick="window.print()">Print Recipe</button></div><div class="container" style="margin-top:28px"><img class="recipe-feature-image" src="assets/generated-broths/{slug}.svg" alt="{esc(title)}"></div><div class="container recipe-layout"><section class="ingredients-panel"><h2>Ingredients</h2><ul>{''.join(f"<li>{esc(x)}</li>" for x in ings)}</ul></section><section class="instructions-panel"><h2>Preparation</h2><ol>{''.join(f"<li>{esc(x)}</li>" for x in steps)}</ol></section></div><div class="container" style="margin-top:28px"><h2>Related Recipes</h2><p>{related}</p></div></main><footer class="footer"><div class="container footer-wrap"><p>© <span id="year"></span> The Kitchen Table</p><a href="index.html#recipes">All recipes</a></div></footer><script src="script.js"></script></body></html>'''
    (ROOT/f"{slug}.html").write_text(page,encoding="utf-8")

# Enhance existing canonical Birria Consomé with local generated art and related broth links.
bp=ROOT/"birria-consome.html"
if bp.exists():
    s=bp.read_text(encoding="utf-8")
    s=re.sub(r'src="[^"]+"(?=[^>]*alt="Birria con Consom)', 'src="assets/generated-broths/birria-consome.svg"', s, count=1)
    if 'Beef Broth →' not in s:
        s=s.replace("</main>",'<div class="container" style="margin-top:28px"><h2>Broth &amp; Stock Guide</h2><p><a class="text-link" href="beef-broth.html">Beef Broth →</a> · <a class="text-link" href="mexican-caldo-de-res.html">Caldo de Res →</a> · <a class="text-link" href="pozole-broth.html">Pozole Broth →</a></p></div></main>')
    bp.write_text(s,encoding="utf-8")

idx=(ROOT/"index.html").read_text(encoding="utf-8")
anchor='<div class="recipe-grid" id="recipeGrid">'
if 'chicken-broth.html' not in idx:
    cards=[]
    for title,slug,region,desc,ings,steps,rels in items:
        # Birria card already exists; avoid duplicate.
        if slug in existing: continue
        search=f"{title} broth stock soup {region}"
        cards.append(f'''<article class="recipe-card" data-category="soups" data-search="{esc(search)}"><img class="recipe-photo" src="assets/generated-broths/{slug}.svg" alt="{esc(title)}"><div class="recipe-card-body"><div class="recipe-meta"><span>Broth &amp; Stock</span><span>{esc(region)}</span></div><h3>{esc(title)}</h3><p>{esc(desc)}</p><a href="{slug}.html" class="text-link">View recipe →</a></div></article>''')
    idx=idx.replace(anchor,anchor+"\n"+"\n".join(cards))
    (ROOT/"index.html").write_text(idx,encoding="utf-8")
print("Built",len(items)-len(existing),"new broth pages; retained Birria Consomé as canonical duplicate.")
